bool verify_password(PgSocket *client, const char *passwd) {
    if (client->user == NULL) {
        elog(ERROR, "No user associated with the client");
        return false;
    }

    const char *stored_passwd = client->user->password;

    if (passwd[0] == '\0' || stored_passwd[0] == '\0') {
        return false;
    }

    if (strncmp(stored_passwd, "md5", 3) == 0) {
        if (strlen(passwd) < 1 || strlen(passwd) > 512) {
            return false;
        }

        char encrypted_passwd[BUFSIZE];
        snprintf(encrypted_passwd, sizeof(encrypted_passwd), "md5%s%s",
                 md5_hash(passwd, strlen(passwd)), client->user->username);

        return strcmp(stored_passwd, encrypted_passwd) == 0;
    } else if (strncmp(stored_passwd, "crypt", 5) == 0) {
        char *encrypted = crypt(passwd, stored_passwd + 6);
