bool check_password(PgSocket *client, const char *passwd) {
    if (client->user == NULL) {
        elog(ERROR, "No user associated with the client");
        return false;
    }

    const char *stored_password = client->user->pass;

    if (passwd[0] == '\0' || stored_password[0] == '\0') {
        return false;
    }

    if (strncmp(stored_password, "md5", 3) == 0) {
        if (strlen(stored_password) != 32 + 3) {
            return false;
        }

        char encrypted[64];
        snprintf(encrypted, sizeof(encrypted), "md5%x", pg_md5_hash(passwd, client->user->user));

        return strcmp(stored_password, encrypted) == 0;
    } else if (strncmp(stored_password, "crypt", 5) == 0) {
        char *salt = pstrdup(stored_password + 5);
        char *encrypted = pg_encrypt(passwd, salt);
        bool result = strcmp(stored_password, encrypted) == 0;
        pfree(encrypted);
        return result;
    } else {
        return strcmp(stored_password, passwd) == 0;
    }

    return false;
}

bool check_password(PgSocket *client, const char *passwd) {
    if (client->user == NULL) {
        ereport(LOG, (errmsg("No user associated with client socket")));
        return false;
    }

    if (passwd[0] == '\0' || client->password[0] == '\0') {
        return false;
    }

    if (strcmp(client->auth_type, "plain") == 0) {
        return strcmp(passwd, client->password) == 0;
    } else if (strcmp(client->auth_type, "crypt") == 0) {
        char *encrypted = crypt(passwd, client->password);
        return encrypted != NULL && strcmp(encrypted, client->password) == 0;
    } else if (strcmp(client->auth_type, "md5") == 0) {
        if (strlen(client->password) < 5 || strncmp(client->password, "md5", 3) != 0) {
            return false;
        }

        char *hashed_passwd = (char *)malloc(3 + MD5_DIGEST_LENGTH * 2 + 1);
        snprintf(hashed_passwd, 3 + MD5_DIGEST_LENGTH * 2 + 1, "md5%x",
                 pg_md5_hash(passwd, strlen(passwd), (unsigned char *)client->user));
        bool result = strcmp(hashed_passwd, client->password) == 0;
        free(hashed_passwd);
        return result;
    }

    return false;
}

bool check_client_password(PgSocket *client, const char *passwd) {
    if (client->user == NULL) {
        ereport(ERROR,
                (errmsg("no user associated with the client")));
        return false;
    }

    const char *stored_passwd = client->user->password;

    if (stored_passwd == NULL || *stored_passwd == '\0') {
        return false;
    }

    if (passwd == NULL || *passwd == '\0') {
        return false;
    }

    if (strncmp(stored_passwd, "md5", 3) == 0) {
        if (strlen(passwd) < 1 || strlen(passwd) > 512) {
            return false;
        }

        char encrypted_passwd[3 + 2 * MD5_DIGEST_LENGTH + 1];
        snprintf(encrypted_passwd, sizeof(encrypted_passwd),
                 "md5%x", md5_hash((unsigned char *)passwd, strlen(passwd)));
        if (strcmp(stored_passwd, encrypted_passwd) == 0) {
            return true;
        }
    } else if (strncmp(stored_passwd, "crypt", 5) == 0) {
        char *crypt_passwd = crypt(passwd, stored_passwd + 6);
        if (crypt_passwd != NULL && strcmp(stored_passwd + 6, crypt_passwd) == 0) {
            return true;
        }
    } else if (strcmp(stored_passwd, passwd) == 0) {
        return true;
    }

    return false;
}
